"""Summarise saved final render runs; no new workload or inference."""
import csv,json
from pathlib import Path
import numpy as np
ROOT=Path.cwd();OUT=ROOT/'reports/stage2'
def aggregate(labels):
 reports=[json.loads((OUT/(label+'.json')).read_text()) for label in labels];frames=[]
 for label in labels:
  rows=csv.DictReader(next((OUT/'raw'/label).glob('frames-*.csv')).open());frames.extend(float(r['wall_frame_interval_ms']) for r in rows if float(r['wall_seconds'])>=5)
 a=np.array(frames)
 return {'frames':len(a),'fps':float(1000/a.mean()),'mean_ms':float(a.mean()),'p95_ms':float(np.percentile(a,95)),'p99_ms':float(np.percentile(a,99)),'max_ms':float(a.max()),'cpu_one_core_mean_percent':float(np.mean([r['native_cpu_one_core_percent']['mean'] for r in reports])),'host_cpu_mean_percent':float(np.mean([r['host_cpu_percent']['mean'] for r in reports])),'native_rss_sampled_peak_mb':max(r['native_rss_bytes']['max'] for r in reports)/1e6,'gpu_device_mean_percent':float(np.mean([r['gpu_device_busy_percent']['mean'] for r in reports])),'packed_each':[r['run']['packed'] for r in reports],'sim_time_each':[r['run']['sim_time'] for r in reports]}
before=aggregate(['before-stage1-1','before-stage1-2']);after=aggregate(['after-stage2-freeze-1','after-stage2-freeze-2']);report={'before_stage1':before,'after_stage2':after,'measured_source':'d516dd3','baseline_source':'cac93c6 (preserved accepted Stage1 binary)','method':'Two35s final runs each; first5s excluded. Common full-viewport fixed overview,1600x900,60target,VSync0,4MSAA,seed42/healthy/1x/PLC, no inference. Initial Stage2 runs retained as checkpoints and excluded from final aggregate.','limits':'Whole-device GPU only; RSS resident process accounting; not disjoint shared memory. Short same-host render comparison, not soak/realPLC/hardware sizing or AI benchmark.'}
(OUT/'performance-summary.json').write_text(json.dumps(report,indent=2)+'\n')
lines=['# Stage 2 rendering comparison','','Accepted Stage1 binary versus Stage2 sourced516dd3. Unity6000.6.5f1 Linux Mono release, Built-in / Standard / OpenGLCore, A395 Ryzen AI Max+395 / Radeon8060S, Ubuntu24.04.5.1600×900, target60FPS,VSync0,4MSAA. Same seed42/healthy/1×/PLC, original overview transform and full77% viewport held by --comparison-camera. The default customer viewport/layout differs; this is a common-view controlled comparison, not a benchmark of every view.','','Two35s runs per version, first5s frame intervals excluded; raw Unity unscaled wall intervals and separate simulated timestamps. Resource warm-up uses5s from process launch, not the Unity Awake clock. Initial Stage2 measurements89cce14/fbe388a are retained checkpoints, excluded after the Data-view-only camera fix. Background inspection service PID41095 remains active; other demos/services unchanged. No inference.','','| Metric | Stage1 | Stage2 |','|---|---:|---:|']
for key,label,suffix in [('fps','Mean FPS',''),('mean_ms','Mean frame',' ms'),('p95_ms','Frame p95',' ms'),('p99_ms','Frame p99',' ms'),('max_ms','Worst frame',' ms'),('cpu_one_core_mean_percent','Native CPU (one core=100%)','%'),('host_cpu_mean_percent','Host CPU (32logical CPU capacity)','%'),('native_rss_sampled_peak_mb','Native sampled peak RSS',' MB'),('gpu_device_mean_percent','Device-wide GPU busy','%')]:lines.append(f'| {label} | {before[key]:.3f}{suffix} | {after[key]:.3f}{suffix} |')
lines+=['',f'Packed counts per run: Stage1 {before["packed_each"]}; Stage2 {after["packed_each"]}. Simulation endpoint seconds: {before["sim_time_each"]} versus {after["sim_time_each"]}; wall-clock stopping can differ by a process tick. No invented exact timing match.','',('Near60FPS retained in this short comparison.' if after['fps']>=59 and after['p95_ms']<18 else 'Rendering regression observed; inspect raw timings.')+' Resource use is reported without claiming a performance benefit or causal GPU allocation. GPU busy is a device-wide sysfs sample including desktop/background work; no process GPU percentages. Native RSS and shared GPU/host memory domains overlap and are not added. No CPU/GPU inference benchmark, comparative appliance result or production-sizing proof.','','Exact commands, config, frames, resource samples and player logs: reports/stage2/raw/{before-stage1-1,before-stage1-2,after-stage2-freeze-1,after-stage2-freeze-2}; JSON summary reports/stage2/performance-summary.json. The final native Data-view screenshots show16.7ms recent frame averages after the camera fix; that display is not a separate percentile benchmark.']
(ROOT/'telemetry/PERFORMANCE.md').write_text('\n'.join(lines)+'\n');print(json.dumps(report,indent=2))
